"use client";

import { motion, useReducedMotion, type Transition } from "motion/react";
import { type ReactNode, useState } from "react";

import { cn } from "@/lib/utils";

/** One person in the row. */
export interface AvatarLiftPerson {
  id: string;
  /** The full name. It names the avatar and shows above it on hover or focus. */
  name: string;
  /** What the circle shows: initials or an image. Defaults to the name's initials. */
  avatar?: ReactNode;
  /** Colour classes for the circle, for example "bg-accent text-accent-foreground". */
  className?: string;
}

/** Props for an avatar row. */
export interface AvatarLiftProps {
  /** Names the row for screen readers, for example "People on this project". */
  label: string;
  people: AvatarLiftPerson[];
  onSelect?: (id: string) => void;
  className?: string;
}

// Two timings on one hover: the avatar rises fast and its scale settles after it. Both ease out
// with no overshoot: neighbours follow, and a bounce would ripple down the row.
const RISE_EASE: Transition = { duration: 0.32, ease: [0.22, 1, 0.36, 1] };
const GROW_EASE: Transition = { duration: 0.61, ease: [0.22, 1, 0.36, 1] };
const LIFT: Transition = { y: RISE_EASE, scale: GROW_EASE };
const INSTANT: Transition = { duration: 0 };

// The chosen avatar rises this far, in rem, and grows by this much.
const RISE = 0.25;
const GROW = 0.05;
// Each step away from the chosen avatar keeps this share of the step before it.
const FALLOFF = 0.45;

// Words that end a name without being part of the initials, such as "Jr." or "III".
const NAME_SUFFIXES = new Set(["JR", "SR", "II", "III", "IV", "V"]);
// Firefox before 125 has no Intl.Segmenter. There the first code point stands in, which keeps an accented letter whole.
const graphemes =
  Intl.Segmenter ? new Intl.Segmenter(undefined, { granularity: "grapheme" }) : null;
const firstGrapheme = (word: string) =>
  graphemes ? (graphemes.segment(word)[Symbol.iterator]().next().value?.segment ?? "") : (Array.from(word)[0] ?? "");
const isSuffix = (word: string) => NAME_SUFFIXES.has(word.replaceAll(".", "").toUpperCase());

// The first character a reader sees in the first and the last word, so an emoji or an accented
// letter stays whole. A suffix counts only at the end, so "V. Patel" keeps its V. An empty result
// means the caller shows a person glyph instead.
function initialsOf(name: string): string {
  const words = name.trim().split(/\s+/).filter(Boolean);
  while (words.length > 1 && isSuffix(words[words.length - 1])) words.pop();
  if (words.length === 0) return "";
  const picked = words.length > 1 ? [words[0], words[words.length - 1]] : [words[0]];
  return picked.map(firstGrapheme).join("").toUpperCase();
}

function PersonGlyph() {
  return (
    <svg viewBox="0 0 16 16" fill="currentColor" aria-hidden="true" className="size-4">
      <circle cx="8" cy="5" r="2.75" />
      <path d="M3 13.25C3 10.75 5.2 9 8 9s5 1.75 5 4.25c0 .4-.35.75-.75.75h-8.5A.75.75 0 0 1 3 13.25Z" />
    </svg>
  );
}

// A tap also focuses the avatar. Only keyboard focus should hold it up.
function focusIsVisible(element: Element) {
  try {
    return element.matches(":focus-visible");
  } catch {
    // An engine without :focus-visible throws on the selector. Treat every focus as visible there.
    return true;
  }
}

/**
 * An overlapping row of avatars. The one under the pointer or the keyboard
 * focus lifts and shows its name, and its neighbours follow it a little.
 */
export function AvatarLift({ label, people, onSelect, className }: AvatarLiftProps) {
  // Each holds a person's id, not a place in the row, so the name stays above the right avatar when the row changes.
  const [hovered, setHovered] = useState<string | null>(null);
  const [focused, setFocused] = useState<string | null>(null);
  const [pressed, setPressed] = useState<string | null>(null);
  const reduceMotion = useReducedMotion();
  const chosenId = pressed ?? hovered ?? focused;
  const chosenIndex = people.findIndex((person) => person.id === chosenId);
  const chosen = chosenIndex === -1 ? null : chosenIndex;

  return (
    <div
      role="group"
      aria-label={label}
      // Escape puts the name away until the pointer or the focus moves on.
      onKeyDown={(event) => {
        if (event.key !== "Escape") return;
        setHovered(null);
        setFocused(null);
      }}
      className={cn("inline-flex items-center pl-2", className)}
    >
      {people.map((person, index) => {
        const isChosen = index === chosen;
        const share = chosen === null || reduceMotion ? 0 : FALLOFF ** Math.abs(index - chosen);
        return (
          <button
            key={person.id}
            type="button"
            aria-label={person.name.trim() || "Unnamed person"}
            data-chosen={isChosen || undefined}
            onClick={() => onSelect?.(person.id)}
            // A touch has no hover: its synthetic one would stick until the next tap.
            onPointerEnter={(event) => {
              if (event.pointerType !== "touch") setHovered(person.id);
            }}
            onPointerLeave={() => {
              setHovered(null);
              setPressed(null);
            }}
            onPointerDown={() => setPressed(person.id)}
            onPointerUp={() => setPressed(null)}
            onPointerCancel={() => setPressed(null)}
            onFocus={(event) => setFocused(focusIsVisible(event.currentTarget) ? person.id : null)}
            onBlur={() => setFocused(null)}
            className={cn(
              "group relative -ml-2 size-11 shrink-0 cursor-pointer touch-manipulation rounded-full outline-none",
              // The chosen avatar sits above the neighbours it overlaps.
              isChosen ? "z-10" : "z-0",
            )}
          >
            <motion.span
              initial={false}
              animate={{ y: `${-RISE * share}rem`, scale: 1 + GROW * share }}
              transition={reduceMotion ? INSTANT : LIFT}
              className={cn(
                "grid size-full place-items-center overflow-hidden rounded-full bg-muted text-sm font-semibold text-foreground ring-2 ring-background",
                "group-focus-visible:ring-ring",
                person.className,
              )}
            >
              <span aria-hidden="true">{person.avatar ?? (initialsOf(person.name) || <PersonGlyph />)}</span>
            </motion.span>
            {/* The name repeats the accessible name for sighted users, so it stays hidden from screen readers. */}
            {isChosen ? (
              <span
                aria-hidden="true"
                className="pointer-events-none absolute bottom-full left-1/2 mb-2 -translate-x-1/2 whitespace-nowrap rounded-md bg-foreground px-2 py-1 text-xs font-medium text-background"
              >
                {person.name}
              </span>
            ) : null}
          </button>
        );
      })}
    </div>
  );
}
